import importlib.util, json
from pathlib import Path
spec = importlib.util.spec_from_file_location('vc','scripts/audit/verify_proof_version_closure.py')
vc = importlib.util.module_from_spec(spec); spec.loader.exec_module(vc)
reg = json.loads(Path('HoTT/verification/PROOF_VERSION_CLOSURE.json').read_text())
later = reg['later_packages']; gap = reg.get('later_package_dependency_gap_allowlist') or {}
ok=0; fails={}
for pkg in later:
    try:
        vc.check_later_package(Path(pkg['run']), pkg, gap); ok+=1
    except Exception as e:
        fails.setdefault(str(e).split(':')[0], []).append(pkg['proof_id'])
print('later_packages:', len(later), 'OK:', ok)
for k,v in fails.items(): print(k, len(v), v[:4])
EOF
